{"CommandLine":"python -c "
import struct, os

def get_image_size(fname):
    try:
        with open(fname, 'rb') as f:
            data = f.read(32)
            if data.startswith(b'\x89PNG\r\n\x1a\n'):
                w, h = struct.unpack('>LL', data[16:24])
                return f'{w}x{h} PNG'
            elif data.startswith(b'\xff\xd8'):
                f.seek(0)
                b = f.read()
                idx = 2
                while idx < len(b) - 9:
                    marker, length = struct.unpack('>2sH', b[idx:idx+4])
                    if marker in [b'\xff\xc0', b'\xff\xc2']:
                        _, h, w = struct.unpack('>BHH', b[idx+4:idx+9])
                        return f'{w}x{h} JPG'
                    idx += 2 + length
                return 'JPG'
    except Exception as e:
        return str(e)
    return 'UNKNOWN'

for root, dirs, files in os.walk('D:/4A'):
    if os.path.basename(root) == '4A 30315' and '2018' in root:
        for f in sorted(files):
            if f.lower().endswith(('.jpg', '.png')):
                fp = os.path.join(root, f)
                print(f'{f:25s} {get_image_size(fp)}')
"","WaitMsBeforeAsync":5000,"toolSummary":"Get 30315 image sizes via walk"}

